Lemma unreg_loop : forall G RNG (lo hi d spv : Z) (ra gp tp t0 t1 t2 s0 a0 a1 a2 a3 a4 a5 a6 a7 s5 s6 s8 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem),
  G <> [] ->
  mem_inv asegs m -> mdtor_rt m -> gdescs m d G -> gshads m G -> gsorted lo hi G ->
  0x10000 <= d -> d + 64 * Z.of_nat (length G) <= 0x60d000 -> 0x7fffa000 <= lo -> hi <= 0x800cd000 -> 0 <= spv < 2^64 ->
  rng_aimg RNG -> rng RNG lo (hi - lo) ->
  evtF asegs RNG (fun ms' => exists (ra' t0' t1' t2' s0' a0' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word) (m' : mem),
      ms' = MS (mkR ra' (Z_to_bv 64 spv) gp tp t0' t1' t2' s0' (Z_to_bv 64 0x1494a8) a0' a1' a2' a3' a4' a5' a6' a7'
                    (Z_to_bv 64 2) (Z_to_bv 64 0x1b232) (Z_to_bv 64 (d + 64 * Z.of_nat (length G))) s5 s6 (Z_to_bv 64 0xb15a8) s8
                    (Z_to_bv 64 0xb5178) (Z_to_bv 64 0xb7978) (Z_to_bv 64 0) t3' t4' t5' t6')
               F (Z_to_bv 64 0x3f838) fc None m' (seg_rom asegs)
      /\ munch [(lo, hi)] m m' /\ wmono asegs m m' /\ mem_inv asegs m')
    (MS (mkR ra (Z_to_bv 64 spv) gp tp t0 t1 t2 s0 (Z_to_bv 64 0x1494a8) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 2) (Z_to_bv 64 0x1b232) (Z_to_bv 64 d) s5 s6 (Z_to_bv 64 0xb15a8) s8 (Z_to_bv 64 0xb5178)
             (Z_to_bv 64 0xb7978) (Z_to_bv 64 (Z.of_nat (length G))) t3 t4 t5 t6)
        F (Z_to_bv 64 0x3f634) fc None m (seg_rom asegs)).
